base.src/passwords.ts:
import { createHash, timingSafeEqual } from 'node:crypto';

export function verifyPassword(hash: string, password: string): boolean {
  const given = createHash('sha256').update(password).digest();
  return timingSafeEqual(given, Buffer.from(hash, 'hex'));
}

base.src/limits.ts:
// How many failed logins an account gets before it's locked.
export const MAX_ATTEMPTS = 5;

export function isOverLimit(attempts: number): boolean {
  return attempts >= MAX_ATTEMPTS;
}

base.src/login.ts:
import { isOverLimit } from './limits.ts';
import { verifyPassword } from './passwords.ts';

export type Account = { attempts: number; hash: string };

/** Checks a password. A locked account never logs in, whatever the password. */
export function login(account: Account, password: string): boolean {
  if (isOverLimit(account.attempts)) return false;
  return verifyPassword(account.hash, password);
}

base.src/reset.ts:
import { isOverLimit } from './limits.ts';
import type { Account } from './login.ts';

/** A locked account can't request a reset link either. */
export function canRequestReset(account: Account): boolean {
  return !isOverLimit(account.attempts);
}

base.test/limits.test.ts:
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { isOverLimit } from '../src/limits.ts';

test('five failed logins lock the account', () => {
  assert.equal(isOverLimit(5), true);
  assert.equal(isOverLimit(4), false);
});

